"""Publish sourced hardware candidates and the staged limb assembly review."""
import csv,hashlib,html,json
from kinematics import ROOT
out=ROOT/'output';stamp=hashlib.sha256((out/'model.json').read_bytes()).hexdigest()
audit=json.loads((out/'limb-assembly-audit.json').read_text());assert audit['model_sha256']==stamp
rows=[('Knee bearings', '8', '6001-2RS; LittleMachineShop / NSK', '12 x 28 x 8 mm', 'US product listing. Bearings sit directly in the structural shin halves. Finish split bore roundness and check free rotation after tightening.', 'https://littlemachineshop.com/products/bearing-6001-2rs'), ('Pushrod bushes', '16', 'igus US GFM-0608-04', '6 ID x 8 OD x 12 flange; 4 mm total length, 1 mm flange', 'Manufacturer dimensions verified. Retain paired flanges for thrust wear protection; four bushes per leg.', 'https://www.igus.com/iglide-ibh/flange-bearings/product-details/iglide-g-m?artnr=GFM-0608-04'), ('Shin clamp screws', '8', 'Amazon US BNUOK M4 x 20 socket cap screws', 'M4 x 0.7; 7 mm head diameter; 4 mm head height', 'Listing dimensions match the nominal envelope. Seller claims grade 12.9; material certification and local delivery date are not verified.', 'https://www.amazon.com/dp/B0DYSQZHC9'), ('M4 captive nuts', '8 plus 8 in printed carrier', 'Standard M4 hex nuts; Amazon US or McMaster', '7 mm across flats; 3.2 mm thickness', 'Match actual nut thickness and flats before printing pockets. Exact Amazon SKU remains unselected.', 'https://www.mcmaster.com/metric-hex-nuts/'), ('Printed carrier screws', '8; printed route only', 'M4 x 16 button-head screws; Amazon US or McMaster', 'ISO 7380 envelope; 7.6 mm head diameter; 2.2 mm head height', 'Two per keyed carrier. Socket-cap heads are too tall for this location. Exact SKU and grade remain unselected.', 'https://www.mcmaster.com/products/metric-button-head-screws/'), ('Pushrod shoulder screws', '8', 'McMaster steel metric shoulder-screw families', 'CAD: 6 mm shoulder x 20 mm, M5 x 6 mm thread, 10 x 5 mm head', 'Catalog 94361A525 has a 5 mm thread and 4.5 mm head; 92981A103 has a 10 mm thread. Neither is an exact unreviewed substitution. Confirm thread engagement or finish the longer threaded tip to the drawing.', 'https://www.mcmaster.com/products/shoulder-screws/fastener-head-type~socket/material~steel-2/'), ('Knee axle retention', '4 screws + 4 flange nuts', 'M8 x 60 button-head screws and M8 flange nuts; McMaster / Fastenal', '14 x 4.4 mm head; nominal nut 13 mm flats, 17.9 mm flange', 'The head is recessed flush to the inner thigh; the nut is outboard. Large removable hardware retains the precision sleeve. Actual nut profile, locking method and preload still need verification.', 'https://www.mcmaster.com/products/metric-button-head-screws/'), ('Knee axle sleeve / inner spacer', '4 each custom', 'Precision steel stock; McMaster', 'Sleeve 12 OD x 8.4 ID x 45.1 mm; inner-race spacer 12 mm long', 'Finish from stock to the bearing-fit drawing. Ordinary hardware-store tubing is not a substitute for a ground bearing seat.', 'https://www.mcmaster.com/precision-shafts/'), ('Shin compression sleeves', '8', 'Aluminum stock; McMaster or Fastenal', '8 OD x 4.3 ID x 16 mm', 'Two captive sleeves per shin; finished length controls clamp stack. Exact off-the-shelf SKU is unselected.', 'https://www.mcmaster.com/metric-spacers/'), ('Hip-roll bearings', '4', 'THK North America RA / RAU 5008 family', 'RA5008 envelope 50 x 66 x 8 mm', 'Specialist exception. Confirm interchangeable model, load/moment capacity, retainers and preload with US distributor; not a general hardware-store item.', 'https://www.thk.com/us/en/products/cross_roller_ring/cross_roller_ring/rau/rau_ra/'), ('Motor screws', '108 stator + 72 output positions', 'M3 stator / M4 output; Amazon US or Fastenal', 'Nine M3 holes on 73 mm circle; six M4 holes on 24 mm circle', 'Pattern count is not a released purchase quantity. Lengths depend on clamp thickness, low-head clearance and delivered motor thread depth.', 'https://robstride.com/products/robStride02'), ('Frame / tray / cover fasteners', 'Per final assembly inventory', 'M3 metric screws and captive nuts; Amazon US', 'M3 x 8 countersunk frame screws; M3 x 12 independent cassette screws', "Keep head styles distinct. Ordinary fasteners use Amazon first; Lowe's is a local fallback, not a required source.", 'https://www.mcmaster.com/metric-screws/'), ('Pushrod and motor ties', 'Custom/provisional', 'Steel link and compression stock from US suppliers', '170 mm eye centers; steel web 6 x 6 mm; M3 motor ties', 'The rod, precise sleeves and motor tie stack remain custom or unfinished interfaces. Do not list them as ready-made Amazon parts.', 'https://www.mcmaster.com/steel/')]
rows.append(('Electronics deck / fixed brace screws','4 M3 x 8 + 4 M3 x 6','Amazon US matching socket-cap screws; McMaster dimensional reference','M3 x 0.5; 5.5 mm head diameter; 3 mm head height','Use standard socket caps, not the countersunk frame-tie screws. Deck and brace have independent attachments. Verify actual tapped engagement; stock and delivery are not confirmed.','https://www.mcmaster.com/products/metric-blue-socket-head-cap-screws'))

fields=['component','robot_quantity','candidate','dimensions','fit_status','source']
records=[dict(zip(fields,row)) for row in rows]
(out/'hardware-research.json').write_text(json.dumps({'model_sha256':stamp,'checked_date':'2026-10-25','status':'Research shortlist, not a purchase-ready BOM','parts':records,'stock_and_prices':'Not verified','scope':'Catalog dimensions and nominal assembly review; no physical fit or load tests.'},indent=2))
with (out/'hardware-shortlist.csv').open('w') as f:
 w=csv.DictWriter(f,fields);w.writeheader();w.writerows(records)
text="TINFOX — STRUCTURAL LIMBS AND US HARDWARE\n\nSourcing\nAmazon.com is the default for ordinary fasteners. McMaster-Carr, Fastenal and\nmanufacturer stores serve precision interfaces. Lowe's is only a local fallback.\nThe table distinguishes dimension matches from catalog candidates. Stock, delivery\nand pricing are not guaranteed. No UK seller is required by this shortlist.\n\nStructural assembly\nThere is no separate knee head or internal bearing-housing block. The two shin\nhalves contain the pushrod rocker, split bearing seats and axial retaining shoulders.\nTheir fore/aft split passes through the bearing axes. Opening the halves releases\nthe bearings radially; no blind pocket, drift slot or third internal housing is used.\nThe thigh remains two structural halves, with its motor face and service ring integral.\nThe hip-side shroud follows hip roll and is part of the motor carrier. The thigh\nmoves independently in pitch, so the shroud cannot bridge those two moving groups.\n\nPrinted carrier\nTwo parts form the printed carrier: a roll-side trunnion and a perpendicular hip\nflange with integral shroud. A broad tongue/socket and two M4 button-head screws\njoin them. The hip flange is 5 mm thick. Print the two main mounting faces in\ndifferent bed orientations. This addresses layer direction but does not qualify\nstrength, clamp creep, temperature resistance or fatigue. Metal carriers remain\none piece. The separate motor-driven input crank is mechanically necessary.\n\nBench assembly and bearing service\n1. Install the captive M4 nuts and compression sleeves into the open shin halves.\n   Seat the M5 pivot nut in its side-loading pocket before closing the structural split.\n2. Place both 6001 bearings and the inner-race spacer directly in the structural\n   semicircular seats. Close the halves against their mating lands and install two\n   M4 x 20 screws. The closure stops must preserve bore roundness and free rotation.\n3. Fit the precision knee sleeve through the thigh and bearing inner races. Retain\n   it with the recessed M8 through-bolt and outboard flange nut. Verify fit and clamp preload on the bench.\n4. Install the paired flanged bushes and shoulder screws at the two pushrod pivots.\n   Preserve their thrust faces and check free movement throughout the knee range.\n5. To replace bearings, support the leg and remove the lower pushrod pivot screw.\n   Release the axle retention and withdraw the precision sleeve. Remove the two\n   M4 shin screws and open the structural halves. Lift out the bearings and spacer.\n   Clean the exposed seats before reassembly; do not force bearings past a shoulder.\n\nFit and force precautions\nThe split housing releases bearings by opening, rather than pressing them axially\nthrough blind stops. The shaft/bushing fits still require controlled assembly force.\nApply force to the race receiving an interference fit, never through bearing balls.\nDo not use the clamp bolts to pull a misaligned bearing into its seat. Use printed\nfit coupons and verify assembled roundness, axle alignment and free running.\nFor CNC, finish critical split bores with the halves fixed against the closure stops.\n\nPrototype status\nThe printed set is for unloaded fit and hand-articulation checks. The knee linkage\ncan produce approximately 1.31 kN rod force at the 17 N m actuator peak reference.\nPrinted forks, motor carrier, clamp seats and bearing lands need physical load,\ncreep and fatigue testing. Solid infill alone does not establish strength.\nRoll-bearing retainers/preload, the motor tie stack, exact screw engagements,\nfoot retention and wiring remain unfinished. No loaded gait is qualified.\n"
(out/'limb-hardware-guide.txt').write_text(text)
tr=''.join('<tr>'+''.join('<td>'+('<a href="'+html.escape(r[k])+'">Supplier / catalog</a>' if k=='source' and r[k] else html.escape(r[k]))+'</td>' for k in fields)+'</tr>' for r in records)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tinfox · hardware and limb assembly</title><style>body{margin:0;background:#eeeee7;color:#293b30;font:16px/1.6 system-ui}main{max-width:1200px;margin:auto;padding:40px}h1,h2{font-weight:500}h1{font-size:40px}a{color:inherit}table{border-collapse:collapse;font-size:13px;width:100%}td,th{padding:14px;border-bottom:1px solid #c4cebf;text-align:left;vertical-align:top}pre{white-space:pre-wrap;font:15px/1.65 system-ui}.notice{padding:18px;background:#dfe5d7;border-left:3px solid #ef803b}.links{display:flex;gap:22px;flex-wrap:wrap}img{max-width:100%}</style><main><nav class="links"><a href="./">CAD</a><a href="manufacturing.html">Print preparation</a><a href="assembly.html">Body assembly</a><a href="parts.html#thigh_outer">Outer thigh</a></nav><h1>Hardware that fits the mechanism.</h1><p class="notice">Research shortlist · checked 25 October 2026. Structural shells directly hold the bearings and rocker. Large axle-retention hardware and two shin clamps are modeled. Bearing fits, motor ties and loaded strength remain unqualified. This is not a purchase-ready BOM.</p><img src="http://127.0.0.1:8769/proposals/sculpted/design/17-face-curvature.svg" alt="Measured horizontal and vertical face curvature"><p class="links"><a href="../output/hardware-shortlist.csv">Hardware CSV</a><a href="../output/integration-audit.json">Bearing service paths</a><a href="variants.html#printed">Printed carrier and knee</a><a href="../output/print-fixtures/dimensional-coupon.step">Fit coupon STEP</a><a href="../output/print-fixtures/dimensional-coupon.stl">Fit coupon STL</a></p><p><a href="http://127.0.0.1:8769/proposals/sculpted/design/20-face-profile.png">Side profile of the curved face</a></p><h2>Components and fit status</h2><div style="overflow:auto"><table><thead><tr>'''+''.join('<th>'+html.escape(v.replace('_',' '))+'</th>' for v in fields)+'''</tr></thead><tbody>'''+tr+'''</tbody></table></div><h2>Assembly and print preparation</h2><pre>'''+html.escape(text)+'''</pre></main></html>'''
(ROOT/'review/hardware.html').write_text(page)
print('Sourced hardware shortlist, assembly sequence and browser review written.')
